Method.Implementation:
// get an instance of JMSGateway and connect to JMSGateway Super Serve #dim tStat As Status set tStat = $$$OK
#dim jmsgateway As EnsLib.JavaGateway.JavaGateway set jmsgateway = "" set topicConnection = "" set topicSubscriber = ""
Set tStat = $$$OK
// get an instance of JMSGateway and connect to JMSGateway Super Server try { Set jmsgateway=##class(EnsLib.JavaGateway.JavaGateway).%New() Set classPath=##class(%ListOfDataTypes).%New() $$$LOGINFO("To connect: " _ ..JavaGateWayHost _ ":" _ ..JavaGateWayPort)
Do classPath.Insert(..JMSJarPath) $$$LOGINFO("JMS Call Path added: " _ ..JMSJarPath) /* For n=1:1:$L(..JMSJarPath,":") { set jarFile = $P(..JMSJarPath,":",n) Do classPath.Insert(jarFile) $$$LOGINFO("JMS Call Path added: " _ jarFile) } */
Set tStat=jmsgateway.%Connect(..JavaGateWayHost,..JavaGateWayPort,$NAMESPACE,5,classPath) If 'tStat { set tStat = $$$ISERR(status) set exp = ##class(%Exception.General).%New() set exp.Code = status.Name set exp.Data = status.Data set exp.Name = "Java Gateway connection error" Throw exp } $$$LOGINFO("Connected to Java Gateway")
set tcf = ##class(com.seebeyond.jms.client.STCTopicConnectionFactory).%New(jmsgateway, ..JMSHost, ..JMSPort) $$$LOGINFO("Connected to JMS: " _ ..JMSHost _ ":" _ ..JMSPort) set topicConnection = tcf.createTopicConnection() do topicConnection.start() $$$LOGINFO("JMS start")
set topicSession = topicConnection.createTopicSession(1, 1) $$$LOGINFO("created topicSession") set topic = topicSession.createTopic(..TopicName) $$$LOGINFO("created topic") set topicPublisher = topicSession.createPublisher(topic)
set message = topicSession.createTextMessage() do message.setText(pRequest.OutputToString()) $$$LOGINFO("JMS msg created") do topicPublisher.publish(message) $$$LOGINFO("JMS published")
do topicSession.commit() Do topicConnection.stop() do topicConnection.close()
Do jmsgateway.%Disconnect()
} catch err { if (topicConnection '= "") { Do topicConnection.stop() Do topicConnection.close() }
Do jmsgateway.%Disconnect() if $GET(%objlasterror) '= "" { set errMsg = $System.Status.GetErrorText(%objlasterror) } else { set errMsg = "No obj" } $$$LOGALERT("Exception: Name: " _ err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " / Details: " _ errMsg) Set tSC=$$$ERROR($$$GeneralError, err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " " _ errMsg)
} Quit tStat
